#include "symrep_io.hpp"
using namespace symrep;
int main(int argc,char**argv){try{
 require(argc==7,"usage boundary_zero_tail_gate EXPERIMENT BOUNDARY prefix_weight finite_letters tail_origin.wxf OUTPUT_STEM");fs::path exp=argv[1],dir=exp/"boundary"/argv[2],stem=argv[6];size_t w=std::stoul(argv[3]),finite=std::stoul(argv[4]);auto start=std::chrono::steady_clock::now();auto origin=read_matrix(argv[5]),p=read_matrix(dir/"collinear"/("first_w"+std::to_string(w)+".wxf")),s=read_matrix(dir/"suffix_TF175_raw2.wxf"),j=read_matrix(exp/"suffix_TR92_to_TF175.wxf");auto h0=read(dir/("H"+std::to_string(w+2)+"_mod_finite_prefix"+std::to_string(w)+"_raw2.wxf"));size_t q=h0.dim(1);auto h=transpose(flatten(h0));h0.clear();require(origin.nrow==p.nrow&&origin.ncol==175&&s.ncol==q*q&&h.ncol==p.ncol,"boundary gate shapes");auto tr=transpose(mul(j,s));s=transpose(s);size_t checked=0,nontrivial=0;Mat residual(q*q,p.ncol);auto ot=transpose(origin);
 for(size_t c=0;c<q*q;++c)if((c/q>=finite||c%q>=finite)&&!tr[c].nnz()){
  ++checked;if(!s[c].nnz()&&!h[c].nnz())continue;++nontrivial;auto raw=mul(s[c],ot);Mat one(1,p.nrow);one[0]=std::move(raw);auto actual=mul(one,p);for(auto[k,x]:h[c])actual[0].push_back(k,-x);normalize(actual[0]);residual[c]=std::move(actual[0]);
 }
 write(stem.string()+"_residual.wxf",residual);std::ofstream receipt(stem.string()+".json");receipt<<"{\"prefix_weight\":"<<w<<",\"all_zero_TR_spurious_suffix_columns_checked\":true,\"checked_columns\":"<<checked<<",\"nontrivial_TF_or_source_columns\":"<<nontrivial<<",\"exact_residual_nonzeros\":"<<residual.nnz()<<",\"all_checks_pass\":"<<(residual.nnz()?"false":"true")<<",\"F4_target_read\":false,\"scope\":\"Necessary affine boundary consistency for suffix pairs annihilating every homogeneous TR92 correction; no sewing or existence conclusion.\",\"seconds\":"<<std::chrono::duration<double>(std::chrono::steady_clock::now()-start).count()<<"}\n";std::cout<<"ZERO_TR_BOUNDARY_GATE columns="<<checked<<" nontrivial="<<nontrivial<<" residual="<<residual.nnz()<<std::endl;
}catch(const std::exception&e){std::cerr<<e.what()<<std::endl;return 1;}return 0;}
